import * as T from './vendor/three.module.js';
export function installMagicSchool({scene,camera,colliders,pause,rewards,getNearbyPlaces=()=>[],getCurrentSeat=()=>null,storage}){
 const root=new T.Group();root.name='Magic School · lantern classroom';scene.add(root);
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.8}),cream=mat('#eee0c5'),purple=mat('#625078'),wood=mat('#8a694b'),gold=mat('#d9b46c');
 const part=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.2,d:d/2+.2});return o;};
 box(-57,.12,140,6.8,.16,9,wood);for(const x of [-60.3,-53.7])box(x,2.2,140,.24,4.4,9,cream,true);box(-57,2.2,135.5,6.8,4.4,.24,cream,true);
 for(const x of [-59.4,-54.6]){box(x,.6,144.5,1.7,1.2,.24,purple,true);const glass=part(new T.PlaneGeometry(1.5,2.5),new T.MeshStandardMaterial({color:'#dacfee',transparent:true,opacity:.25,side:T.DoubleSide,depthWrite:false}),x,2.55,144.51);glass.castShadow=false;box(x,4.1,144.5,1.7,.6,.24,purple);}
 box(-57,4.5,140,7.1,.3,9.5,purple);box(-57,3.7,145.1,6.8,.15,1.4,purple);
 const seats=[];for(const x of [-58.8,-55.2]){box(x,1,138.8,1.3,.15,1,wood,true);box(x,.5,138.8,.12,1,.12,gold);box(x,.6,140.5,.85,.2,.8,purple,true);box(x,1,140.85,.85,.8,.12,wood);seats.push({name:'Magic School desk chair',x,z:140.5,y:1.5,yaw:0,approach:{x,z:141.8},kind:'school'});}
 box(-57,2,135.7,5.7,2.5,.1,purple);
 const colors=['#96949f','#e7bf65','#5dc6c3','#e590bc'],names=['Unlit','Gold','Teal','Rose'],target=[1,2,3],selected=[0,0,0],lanterns=[];
 const progressKey='krownlandia-school-pattern-v1';let progressSaved=true;try{storage=storage||localStorage;const value=JSON.parse(storage.getItem(progressKey)||'null');if(Array.isArray(value)&&value.length===3&&value.every(n=>Number.isInteger(n)&&n>=0&&n<=3))value.forEach((n,i)=>selected[i]=n);}catch{progressSaved=false;}
 function savePattern(){try{storage.setItem(progressKey,JSON.stringify(selected));progressSaved=true;}catch{progressSaved=false;}}
 for(let i=0;i<3;i++){const glow=new T.MeshStandardMaterial({color:colors[0],emissive:colors[0],emissiveIntensity:.1});lanterns.push(part(new T.OctahedronGeometry(.3),glow,-59+i*2,2.5,136.1));}
 const star=part(new T.OctahedronGeometry(.48),new T.MeshStandardMaterial({color:'#ffe7a0',emissive:'#ffd66c',emissiveIntensity:.7}),-57,3.6,137.7);star.name='Magic School completed lantern star';star.visible=false;
 function sign(text,x,y,z,w,h){const c=document.createElement('canvas');c.width=Math.round(w*160);c.height=Math.round(h*160);const ctx=c.getContext('2d');ctx.fillStyle='#473d63';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff0c8';ctx.textAlign='center';ctx.textBaseline='middle';let size=c.height*.5;ctx.font=size+'px Georgia';size*=Math.min(1,c.width*.92/ctx.measureText(text).width);ctx.font=size+'px Georgia';ctx.fillText(text,c.width/2,c.height/2);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;part(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign('MAGIC SCHOOL',-57,4.1,145.21,5,.65);sign('LANTERN PATTERN · GOLD · TEAL · ROSE',-57,1.5,135.8,5.6,.45);
 const deskPoint={x:-57,z:137.5,name:'Magic School lantern-pattern classroom'},near=()=>Math.hypot(camera.position.x-deskPoint.x,camera.position.z-deskPoint.z)<1.6;
 const canStudy=()=>near()||seats.includes(getCurrentSeat());
 const dialog=document.createElement('dialog');dialog.id='schoolMenu';dialog.setAttribute('aria-labelledby','schoolTitle');const title=document.createElement('h2');title.id='schoolTitle';title.textContent='Magic School · First lesson';const intro=document.createElement('p');intro.textContent='Magic School was contributed by @elizabeths14 to the original places list. This west-bank classroom and lantern-pattern puzzle are our interpretation of that idea.';const instruction=document.createElement('p');instruction.textContent='Match the lanterns from left to right: Gold, Teal, Rose. Each button cycles its lantern through Unlit, Gold, Teal and Rose.';const status=document.createElement('p');status.id='schoolStatus';status.setAttribute('role','status');const controls=document.createElement('div'),buttons=[];
 const nearby=document.createElement('details');nearby.id='schoolNearby';const nearbyTitle=document.createElement('summary');nearbyTitle.textContent='Explore nearby';const nearbyList=document.createElement('div');nearby.append(nearbyTitle,nearbyList);
 function refreshNearby(){nearby.open=false;nearbyList.replaceChildren();for(const point of getNearbyPlaces()){const button=document.createElement('button');button.id='schoolWalk-'+point.id;button.textContent='Walk to '+point.name;button.onclick=()=>{if(!canStudy())return;pause();rewards.guideToPoint({x:point.x,z:point.z,name:point.name});dialog.close();};nearbyList.append(button);}nearby.hidden=nearbyList.children.length===0;}
 const done=()=>rewards.state().done.includes('school-pattern');
 function refresh(){const complete=done();if(complete)target.forEach((value,i)=>selected[i]=value);selected.forEach((value,i)=>{lanterns[i].material.color.set(colors[value]);lanterns[i].material.emissive.set(colors[value]);lanterns[i].material.emissiveIntensity=value?.65:.1;buttons[i].textContent='Lantern '+(i+1)+': '+names[value];buttons[i].disabled=complete;});star.visible=complete;const st=rewards.state();status.textContent=st.claims.includes('school:task')?'Lesson complete · Your task reward is collected.':complete?'Pattern matched! Your star is lit and 20 task points are ready at the Magic School rewards station.':'Match all three lanterns to light the classroom star.';if(complete)status.textContent+=' Your First Lesson Star is in the keepsake journal and can be displayed at home.';if(!complete&&selected.some(Boolean)&&progressSaved)status.textContent+=' Your lantern pattern is saved for your next visit.';if(!st.saved||(!complete&&!progressSaved))status.textContent+=' Progress lasts for this visit only.';}
 for(let i=0;i<3;i++){const b=document.createElement('button');b.id='schoolLantern-'+i;b.onclick=()=>{if(!canStudy()||done())return;selected[i]=(selected[i]+1)%4;savePattern();if(selected.every((value,j)=>value===target[j]))rewards.completeSchool();refresh();};buttons.push(b);controls.append(b);}
 const go=document.createElement('button');go.id='schoolRewards';go.textContent='Find school rewards';go.onclick=()=>{rewards.guideTo('school');dialog.close();};const close=document.createElement('button');close.id='schoolClose';close.textContent='Return to the classroom';close.onclick=()=>dialog.close();dialog.append(title,intro,instruction,controls,status,go,nearby,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='school.css';document.head.append(css);refresh();
 return {seats,deskPoint,progress:()=>({started:selected.some(Boolean),saved:progressSaved}),collection:()=>done()?[{id:'school-first-star',name:'First Lesson Star',color:'#76638b'}]:[],get near(){return near()},get isOpen(){return dialog.open},open(){if(!canStudy()||dialog.open)return false;pause();refresh();refreshNearby();dialog.showModal();return true;}};
}
